      story:
        '«Оппонент» посвящён одной из глав современной жизни Джея Гэтсби — моменту, где он сталкивается с мужем своей возлюбленной, Томом Бьюкененом.\n\nТом здесь не просто человек из прошлого. Он — тень, которая нависает над настоящим Гэтсби. Его присутствие ощущается как проницательный укор: взгляд становится холоднее, воздух плотнее, а атмосфера вокруг начинает темнеть.\n\nВ коктейле это напряжение передано через горечь Campari и Fernet-Branca, сухую травянистость шалфея, пряную глубину чёрного кардамона и плотный тон красного вермута. Земляничный сироп добавляет сладкую, почти парфюмерную ноту — как воспоминание о красивой жизни, в которой за блеском всегда скрывается тревога.\n\n«Оппонент» — это коктейль о столкновении прошлого и настоящего. О моменте, когда роскошь перестаёт быть декорацией, а становится сценой внутреннего конфликта.',
