      barDescription:
        'Данила Байдин создал «Спортсмены» как минималистичный коктейль, вдохновлённый супрематизмом и эстетикой Малевича. Напиток собран без сложных заготовок: только водка, Suze и Skinos. Вкус строится на неожиданном эффекте — из простой крепкой базы, горького французского аперитива и сладкого греческого ликёра рождается ассоциация со свежей сладкой морковью. Визуальная подача с цветными мазками на бокале поддерживает идею картины и превращает коктейль в ироничный барный холст. Сейчас в баре не работает, служит в церкви.',
