      intro:
        '«Спортсмены» — минималистичный коктейль по формуле Negroni, вдохновлённый супрематизмом и картиной Малевича. Водка даёт простую чистую базу, Suze отвечает за горечь, Skinos — за сладость и аромат. Неожиданно вместе они складываются во вкус свежей сладкой моркови — почти с бабушкиной грядки, но в постмодерновой барной форме.',
      story:
        '«Спортсмены» — коктейль, который сложно назвать прямым твистом на Negroni. Скорее, это напиток, собранный по похожей формуле: крепкая база, сладкий ароматический компонент и горькая часть.\n\nАвтор честно признаётся, что не любит притянутый за уши сторителлинг. Поэтому здесь история не пытается быть сложнее самого напитка. Всё наоборот: в основе — минимализм, простота и супрематическая логика. Без премиксов, пен, кордиалов и молекулярных конструкций.\n\nВодка работает как чистая основа. Skinos отвечает за сладость и узнаваемый мастиковый аромат. Suze добавляет горечь, травянистость и сложность. В результате сочетание простой водки, сложного Suze и необычного Skinos неожиданно даёт во вкусе свежую сладкую морковь — не грубую овощную, а почти попсовую, яркую и понятную.\n\nВ этом есть что-то постмодерновое: сложные ингредиенты становятся надстройкой над простой базой и в итоге приводят не к элитарной абстракции, а к образу обычного русского корнеплода.\n\nКрасный, синий и зелёный мазки на бокале отсылают к цветам картины, а чуть желтоватый оттенок коктейля работает как холст. Минимализм, ирония, водка, морковь и Малевич — Казимир Северинович бы, возможно, кайфанул.',
