      story:
        'Если проводить параллели между музыкой и напитками, то сладко-горький профиль Negroni естественно ассоциируется с джазом. О джазе говорят как о музыке, в которой одну и ту же ноту можно играть ночь за ночью — и каждый раз по-разному.\n\nТак же работает и Negroni. Его состав кажется простым и понятным, но в каждом баре он звучит иначе: где-то суше, где-то плотнее, где-то горче, где-то с более яркой ароматикой.\n\nВ Rat Pack Negroni классическая формула получает характерные ноты Нового Орлеана — родины джаза. Анис добавляет пряную, почти ликёрную глубину, кофе усиливает тёмный, бархатный профиль вермута, а шоколадный трюфель в гарнире поддерживает десертно-горькую сторону напитка.\n\nНазвание отсылает к Rat Pack — творческому содружеству звёзд шоу-бизнеса, связанному с образами Дина Мартина и Фрэнка Синатры. Поэтому этот коктейль звучит как вечерний джазовый стандарт: знакомая тема, но с новой импровизацией.',
