      story:
        'Бесконечность — понятие необъятное и почти непостижимое для человека в рамках его быстротечной жизни. Но иногда идеи оказываются сильнее времени и продолжают жить после своего автора.\n\nИльдар Ханов создал проект, который продолжается и после его смерти, — Храм всех религий. Это место единения, силы и символического диалога между разными культурами, верованиями и взглядами.\n\nДля коктейля была выбрана формула Negroni — ещё одного героя современности. Вариации на этот напиток уже сами приблизились к бесконечности: каждый бар, каждый автор и каждая эпоха находят в нём свой угол, свой ритм и свою новую форму.\n\nВ версии Cult bar классическая горько-сладкая структура получает более тёмное, плотное и почти десертное звучание. Джин и Campari сохраняют узнаваемый каркас Negroni, Fernet-Branca добавляет травянистую глубину и горечь, красный вермут даёт объём, а какао и вишня с бобами тонка переводят коктейль в сторону насыщенного, пряного и обволакивающего вкуса.\n\n«Бесконечность» — это коктейль о продолжении. О том, как идея получает новую жизнь, меняет форму, но не исчезает.',
