      story:
        'Иногда вкус — это воспоминание. А иногда — путь, которым ты идёшь, чтобы не забыть, кто ты есть.\n\nBacio Russo — поцелуй, который соединил три города, три духа и три культуры.\n\nОн начался во Владивостоке — на краю России, где барная стойка ощущается как граница миров. Здесь коктейль звучит как ветер с залива: терпкий, как чай тегуань инь, с оттенком жасмина и солёного воздуха. Это место силы, где Восток не декорация, а естественная природа вкуса. В напитке живёт движение, свобода и азиатская тонкость.\n\nЗатем путь проходит через Казань — город, где вкус обретает вес. Бальзам «Бугульма» становится сердцем рецепта: тёплым, густым, пряным, словно память предков. Казань даёт коктейлю силу корней, глубину обрядов и характер.\n\nА после — Флоренция. Родина Negroni. Город, где каждый аперитив — это жест, стиль и форма. Отсюда в коктейле появляется красный биттер, горечь как искусство и джин — точный и чистый, как линия скульптора.\n\nBacio Russo стал встречей этих трёх миров: поцелуем между Востоком и Западом, между сладостью вишни и горечью Campari, между барной стойкой и душой.\n\nЭто не просто коктейль — это история, рассказанная в бокале. История про путь, вкус и момент, который оставляет след.',
