        'LAO — авторская вариация Negroni, где классическая горечь итальянского аперитива встречается с яркой природой азиатских дистиллятов. Байцзю даёт сложный ферментированный профиль, водка смягчает структуру, виноградный соджу добавляет фруктовую мягкость, а молочный сироп с ванилью округляет вкус и уравновешивает горечь Campari.',
      story:
        'LAO — авторская вариация Negroni, в которой классическая горечь итальянского аперитива встречается с яркой натурой азиатских дистиллятов.\n\nВ основе коктейля — байцзю Нюлан Шаньченян. Он даёт напитку сложный, ферментированный и выразительный профиль: не просто крепость, а характер, глубину и узнаваемую азиатскую ароматику.\n\nРусская водка смягчает композицию и делает вкус чище, виноградный соджу добавляет фруктовую округлость, а Campari сохраняет связь с классической горькой логикой Negroni.\n\nМолочный сироп с ванилью работает как текстурный элемент. Он придаёт напитку мягкость, округлость и лёгкий сливочно-ванильный оттенок, который уравновешивает горечь и кислотность.\n\nНазвание LAO отсылает к идее почтительности и признания. Поэтому коктейль одновременно уважает традицию Negroni и движется вперёд — в сторону азиатских дистиллятов, другой ароматической логики и более мягкой текстуры.\n\nЭто не прямое повторение классики, а аккуратный жест в её сторону: знакомая горько-сладкая структура, переосмысленная через байцзю, соджу и молочную округлость.',
