      story:
        '«О-кунинуси» — коктейль из серии «Японские мифы», посвящённый образу милосердия, которое способно изменить судьбу.\n\nСудьба порой висит на волоске — как у несчастного зайца, обречённого на муки. Но там, где другие прошли мимо, великодушный О-кунинуси протянул руку помощи. В этом жесте рождается главная идея напитка: доброта не выглядит громко, но именно она способна переплести путь человека, мифа и памяти.\n\nКоктейль передаёт эту тему через мягкий, светлый и обволакивающий вкус. Джин задаёт чистую структуру, Campari добавляет горечь и держит связь с формулой Negroni, Vermouth Bianco смягчает профиль, кокосовый ликёр даёт нежную округлость, а shiso liquor приносит зелёную травянистость и японский акцент.\n\nЦвет напитка — нежно-розовый, как утренняя заря над Ягамихиме. Во вкусе он раскрывается кокосовой мягкостью, играет травяными нотами шисо и оставляет лёгкий шёпот вермута в послевкусии.\n\n«О-кунинуси» — это жидкое воплощение доброты: мягкое, светлое, травяное и чуть горькое, как напоминание о том, что милосердие тоже может быть силой.',
