      story:
        '«Оникс» — фирменная вариация на Negroni из первой коктейльной карты бара «АРХИВ» в Воронеже.\n\nКоктейль назван в честь камня оникс, который традиционно воспринимается как мощный амулет и символ защиты. В этой идее есть связь с самим вкусом напитка: он тёмный, собранный, пряный и немного мистический.\n\nГлавный ингредиент коктейля — инфьюз джина на луми, сушёном лайме. Это пряность, характерная для стран Ближнего Востока и Персидского залива. Луми имеет тёмный, почти чёрный цвет и визуально действительно напоминает камень. Во вкусе он даёт сухой цитрусовый профиль, лёгкую терпкость, пряность и ощущение глубины.\n\nКлассическая структура Negroni здесь сохраняется через джин, красный вермут и Campari, но становится более сухой и сложной за счёт Garrone Dry, лимонного биттера и инфьюза на луми. Напиток звучит крепко, горько, пряно и цитрусово, без лишней сладости.\n\nПодача со стальной ватой, которая тлеет перед гостем, создаёт ассоциацию с трансформацией луми: когда-то он был свежим лаймом, а затем стал высушенной тёмной пряностью. Это не просто украшение, а визуальная часть истории — момент превращения свежего в тёмное, яркого в глубокое, простого в символическое.',
