      intro:
        'Count P. Kobyakov — русский Negroni, посвящённый дедушке автора, художнику и архитектору Петру Андреевичу Кобякову. В основе — дистиллят из винного сусла сорта Ркацетели, Supreme Antica Formula, Campari Negroni, артишоковый биттер и ореховый аперитив. Коктейль выдерживается в бочке из кавказского дуба, а при подаче получает ароматический акцент ройбуша.',
      story:
        'В Negroni автор всегда видел историю и связь с предками — связь, которая длится веками, не теряя ни актуальности, ни собственного смысла. Именно это ощущение преемственности стало основой коктейля Count P. Kobyakov, или «Граф П. Кобяков».\n\nНапиток посвящён дедушке автора — Петру Андреевичу Кобякову, известному художнику, который открыл собственную художественную школу в Богородицке. В неё съезжались ученики со всей округи. Богородицк известен не только своей историей, но и дворцом графов Бобринских, который после военных разрушений нуждался в восстановлении.\n\nПетра Андреевича пригласили на должность архитектора для восстановления и реставрации дворца. После блестяще выполненной работы ему самому вручили статус графа. Поэтому этот коктейль — не просто авторская вариация на Negroni, а личная дань уважения человеку, который пытался сделать мир лучше не из корысти, а из чистого сердца.\n\nИнгредиенты напитка символизируют художественные направления, в которых работал дедушка автора. Дистиллят из винного сусла сорта Ркацетели даёт цветочный профиль с оттенком фиалки. Supreme Antica Formula добавляет винную глубину и благородную сладость. Campari Negroni сохраняет горькую классическую структуру, артишоковый биттер добавляет сухую растительную грань, а французский ореховый аперитив раскрывает тёплый ореховый тон.\n\nВыдержка в бочке из кавказского дуба связывает ингредиенты в цельную, плотную и зрелую композицию. А несколько капель ароматического биттера из африканского ройбуша при подаче добавляют чайный, сухой и чуть древесный акцент.\n\nCount P. Kobyakov — это Negroni как семейная память: фиалка, орехи, чай, горечь, дуб и уважение к человеку, оставившему после себя дело, школу и след.',
