      story:
        'BLOODBERRY NEGRONI был создан в контексте 4-й лабораторной работы бара Ginstitute, посвящённой растительному составу джина.\n\nВ этой версии Negroni акцент смещён в сторону ягодной глубины и травяной структуры. Брусника даёт сухую лесную кислотность, лёгкую терпкость и северный ягодный характер. Вишнёвая линия раскрывается через sour cherry bitter и поддерживает название коктейля: вкус становится тёмнее, плотнее и ближе к образу кроваво-ягодного Negroni.\n\nMartini Riserva Rubino добавляет винную сладость, травянистость и объём. Red bitter удерживает напиток в горькой аперитивной логике, а porto добавляет мягкую винную глубину и округлость.\n\nСу-вид помогает связать бруснику, джин, вермут и биттеры в единый профиль, не разрушая свежесть ягод. В результате коктейль получается максимально округлым: ягодным, травянистым, умеренно горьким и сухим по сладости.',
