      story:
        '«ГЕНЕРАЛ» был создан в контексте коллаборации GINTL x «Беспринципные».\n\nГенерал — один из главных героев сериала, и именно по его чертам был собран этот тонкий оммаж на белый Negroni. В напитке нет тяжёлой драматичности классического красного Negroni: здесь профиль суше, светлее, строже и травянистее.\n\nGINTL Dry задаёт чистую джиновую основу. Cocchi Americano добавляет винную горечь, цитрусовую свежесть и аперитивную структуру. Fino усиливает сухость и делает вкус более вытянутым, почти хересным. Bitter Bianco и Luxardo Aperitivo Verde дают горько-травяной каркас, а Martini Bianco смягчает композицию и добавляет лёгкую сладость.\n\nOrange bitter завершает вкус цитрусовым акцентом, связывая сухую винную часть, горечь и травянистость.\n\n«ГЕНЕРАЛ» — это белый Negroni с характером: строгий, сухой, травяной и горький, но при этом собранный и элегантный.',
