      barDescription:
        'Марк Пермяков создал коктейль «Дух Экстаза» как авторскую интерпретацию Negroni, вдохновлённую эстетикой Rolls-Royce и символом Spirit of Ecstasy. В центре идеи — ручная работа, внимание к деталям и образ черешневой косточки, которая превращается во вкусе в терпкий миндально-косточковый акцент. Джин, портвейн, Doragrossa Bitter, Luxardo Cherry, Amaretto, Fino и cherry-сироп формируют насыщенный вишнёво-горький профиль с автомобильной элегантностью и барной точностью.',
