        'Seng — свекольно-ореховая вариация на Negroni, вдохновлённая образом монаха, аскетизмом и пересечением культур. Джин на свёкле соединяется с ореховым ликёром Frangelico, пряным вермутом Martini Ambrato и травяной горечью Martini Bitter. Вкус получается землистым, ореховым, умеренно сладким и травянистым.',
      story:
        'Seng переводится как «монах». Название отражает главную идею коктейля — уважение к аскетизму, внутренней дисциплине и образу жизни, связанному с упражнениями ума и воли.\n\nБуддизм стал одним из важнейших элементов китайской цивилизации. Он принёс в культуру идеал бодхисаттвы — существа, которое стремится достичь пробуждения ради блага всех живых существ. Путешествующие монахи распространяли учение, соединяя разные территории, традиции и способы мышления.\n\nЭта идея культурного движения легла в основу напитка. Коктейль объединяет ингредиенты, связанные с разными странами и религиозными традициями.\n\nДжин на свёкле отсылает к простой пище и аскетичному укладу. Свёкла формирует землистый, сладковатый профиль и создаёт основу для сочетания с орехом.\n\nFrangelico добавляет фундук, мягкость и пряность. История ликёра связана с образом христианского монаха, что поддерживает общую концепцию напитка. Вермут Martini Ambrato приносит ноты пряностей, трав и полыни, а Martini Bitter формирует характерную аперитивную горечь с долгим растительным послевкусием.\n\nСвёкла и орех — известное гастрономическое сочетание. В коктейле их связь раскрывается через землистость, сладость, маслянистую ореховую округлость и травяную горечь.\n\nSeng — это напиток о сдержанности, дисциплине и встрече культур, выраженной через простые, но насыщенные вкусовые образы.',
