        'Afrodita Negroni — южная гранатовая интерпретация классического Negroni. Джин Barrister B47 и Campari соединяются с армянским гранатовым вином, гранатовым соком и наршарабом, создавая насыщенный фруктово-горький профиль с плотной текстурой и выразительным гранатовым характером.',
      story:
        'Согласно легенде, первое гранатовое дерево посадила сама Афродита — богиня любви и красоты. Этот образ стал отправной точкой для создания Afrodita Negroni.\n\nВ Cocos Bar классическую формулу переосмыслили через вкусы юга. Красный цвет, терпкость и насыщенность граната поддерживают эмоциональный образ напитка: любовь, чувственность, красота и внутренняя сила.\n\nАрмянское гранатовое вино заменяет привычную винную основу классического Negroni и добавляет ягодную глубину, мягкую терпкость и фруктовую сладость. Гранатовый сок делает вкус более сочным и свежим, а наршараб усиливает плотность, концентрацию и характерную кисло-сладкую гранатовую ноту.\n\nДжин Barrister B47 формирует крепкую ароматическую основу, а Campari сохраняет узнаваемую горечь и связь с итальянской классикой.\n\nAfrodita Negroni — это признание в любви к локальным продуктам и южной культуре. Коктейль соединяет классическую аперитивную структуру с ярким гранатовым вкусом, превращая Negroni в более сочный, эмоциональный и солнечный напиток.',
