      intro:
        'Vitruvian Negroni — архитектурная интерпретация классического Negroni, построенная на гармонии трёх равных частей: крепкой, винной и горькой. London Dry Gin и грейпфрутовый Ginato формируют цитрусовую основу, Vermouth Bianco добавляет мягкость, а сочетание Campari и Aperol делает горечь более яркой и деликатной.',
      story:
        'Античные архитекторы стремились понять гармонию мира через пропорции. Гармония сооружений, а позднее и образ идеального человека описывались точными соотношениями, в которых каждая часть была связана с целым.\n\nТак же строится и идеальный коктейль.\n\nNegroni — одна из самых узнаваемых барных формул в мире. Его классическая конструкция основана на трёх равных частях: крепкой, винной и горькой. В Vitruvian Negroni эта пропорция сохраняется, но каждый блок получает более светлое и деликатное прочтение.\n\nЗа крепкую часть отвечают два джина. London Dry Gin создаёт сухую можжевеловую основу, а Ginato Grapefruit добавляет яркий цитрусовый аромат и лёгкую фруктовость.\n\nВинную часть представляет сладкий белый вермут Bianco. Он делает композицию мягче, округлее и светлее по характеру.\n\nГорькая часть разделена между миланским Campari и венецианским Aperol. Campari сохраняет классическую глубину и травяную горечь, а Aperol добавляет более мягкие цитрусовые и сладковатые оттенки.\n\nСолевой раствор усиливает вкус и помогает связать между собой можжевельник, грейпфрут, вермут и биттеры.\n\nVitruvian Negroni — это коктейль о балансе, в котором классическая формула сохраняет свои пропорции, но становится ярче, легче и деликатнее.',
