      story:
        'Illegal Bar всегда отличался крафтовым подходом к созданию напитков: команда работает не только со вкусом, но и с визуальной подачей, названиями и неожиданными сочетаниями ингредиентов.\n\nTom&Cherry Negroni был создан всей командой бара во время обновления меню в 2024 году. Главная идея напитка — показать гостям, что даже нестандартные гастрономические ингредиенты могут органично дополнять классическую формулу коктейля.\n\nВ основе сохраняется узнаваемая структура Negroni: джин, красный сладкий вермут и Campari. Однако смесь настаивается на вишне и вяленых томатах. Вишня усиливает фруктовую глубину, сладость и терпкость, а вяленые томаты добавляют плотность, насыщенность и выраженный гастрономический характер.\n\nДомашний свекольный ликёр расширяет композицию. Свёкла даёт землистую сладость и плотный цвет, бренди добавляет зрелые фруктовые оттенки, а кардамон, корица, сычуаньский перец, гвоздика, кориандр и чёрный перец создают сложную пряную основу.\n\nТростниковый и медовый сиропы делают текстуру более округлой, а лимонная кислота удерживает баланс и не позволяет сладости стать чрезмерной.\n\nTom&Cherry Negroni показывает, как знакомый коктейль может стать площадкой для эксперимента. Томаты, вишня и свёкла не разрушают классическую формулу, а раскрывают её с новой гастрономической стороны.',
