      intro:
        'Ragnar’s Negroni — яркая авторская вариация на Negroni, вдохновлённая образом великого викинга. Джин на тимутском перце, микс красного и белого вермутов на кумквате, Campari и осветлённый эликсир каламанси–пало санто создают пряный, цитрусовый и сладко-горький вкус с выраженной глубиной и ярким ароматическим профилем.',
      story:
        'Скооол, ясноликие северяне!\n\nУ каждого хорошего викинга, по задумке автора, есть три неотъемлемые составляющие жизни.\n\nПервая — мечта. Она подобна быстроходному драккару, который помогает двигаться за горизонт, вперёд — со страстью, доблестью и отвагой.\n\nВторая — бесстрашие. Ведь плох тот воин, который не смеётся смерти в лицо, не испытывает судьбу и не пытается прыгнуть выше собственной головы.\n\nТретья — любовь. Любовь к женщине, к открытиям, к жизни, к наживе, к Одину, к новым землям — и, конечно, к правильным эликсирам, которые пьянят тело, но приводят к балансу дух.\n\nИменно этим трём силам посвящён Ragnar’s Negroni — напиток, созданный в честь великого народа, который побывал почти на всех континентах задолго до их официального открытия, и в честь легендарного викинга и завоевателя Рагнара Кожаные Штаны.\n\nДля такого персонажа нужны великие сочетания. Поэтому в этом эликсире соединяются разные части света:\n\nНепал — через тимутский перец;\nАзия — через кумкват и каламанси;\nЮжная Америка — через сироп пало санто;\nИталия — через базовую структуру Negroni и Campari.\n\nНо главное, что остаётся в напитке от викингов, — это не ингредиенты, а сами принципы: мечта, бесстрашие и любовь.',
