      story:
        'Aztec Negroni — один из культовых напитков El Copitas Bar и важная часть идентичности бара.\n\nИменно с этим коктейлем команда выиграла конкурс Tahona Society в Мексике в 2017 году, поэтому напиток стал не просто авторской вариацией на Negroni, а полноценной визитной карточкой проекта.\n\nВ основе рецепта — смещение классической джиновой оси в сторону агавовых дистиллятов. Текила даёт структуру, ясность и сухую основу, а мескаль добавляет дымный, более глубокий и выразительный характер. Красный вермут россо сохраняет винную мягкость и сладость, Campari удерживает узнаваемую горькую архитектуру Negroni, а шоколадный биттер добавляет тёплый пряный акцент и связывает вкус с декоративной подачей.\n\nПодача с шоколадным черепом на деревянном ноже усиливает мексиканское настроение коктейля и делает его визуально запоминающимся. Апельсиновая цедра добавляет свежий ароматический штрих и завершает композицию.\n\nAztec Negroni — это коктейль, в котором классическая формула Negroni соединяется с мексиканским темпераментом, агавовой глубиной и фирменной эстетикой El Copitas Bar.',
