      story:
        'В основе Dior Negroni лежит авторское прочтение истории и эстетики модного дома Dior.\n\nДля Михаила Шкультина образ Dior связан с возвращением женственности, элегантности и внимания к форме. Эта идея обновления классики стала отправной точкой для создания напитка: сохранить узнаваемую конструкцию Negroni, но сделать её легче, ярче и ближе к современной аудитории.\n\nLondon Dry Gin формирует сухую и ароматную основу. Campari сохраняет характерную горечь классического коктейля. Клубничный соджу смягчает композицию, добавляя лёгкий ягодный профиль, а кордиал из клубники и фруктов делает вкус сочнее и свежее.\n\nВ результате получается современная вариация на Negroni с меньшей визуальной и вкусовой строгостью. Напиток сохраняет связь с классикой, но раскрывается через клубнику, фруктовую кислотность и более мягкую текстуру.\n\nПо авторской задумке, Dior Negroni должен быть элегантным, стильным и актуальным — коктейлем, который подойдёт как любителям классического Negroni, так и гостям, только начинающим знакомство с горькими аперитивными напитками.',
