      story:
        'Belavibe передаёт атмосферу, в которой мифологическое мышление переплетается с лёгкостью и памяркоўнасцю белорусской культуры.\n\nНапиток задуман крепким, горьким и постепенно затягивающим гостя в мистическое переживание. При этом в нём сохраняется сказочность — ощущение мира, где привычные правила меняются, а чтобы оставаться на месте, приходится двигаться вдвое быстрее.\n\nКлюквенный джин формирует яркую ягодную основу. Кисловато-терпкий характер клюквы соединяется с интенсивной травяной ароматикой саган-дайля. Martini Fiero добавляет сладость, цитрусовые оттенки и мягкий винный объём.\n\nБиттер «Крамбамбуля» завершает композицию выраженной горечью и поддерживает культурную связь с Беларусью. В результате получается плотный аперитивный коктейль, в котором ягодность постепенно сменяется травянистостью и продолжительным горьким послевкусием.\n\nBelavibe отражает образ родной культуры без буквального воспроизведения традиционных вкусов. Это современная интерпретация белорусского настроения — сдержанного, загадочного и узнаваемого.',
