      story:
        'Beetroot Negroni переосмысливает классический Negroni через вкусы, близкие русской гастрономической культуре.\n\nВ основе коктейля — свёкла, продукт с насыщенной землистой сладостью и глубоким ароматом. В джиновой заготовке она соединяется со свежей малиной: ягода делает профиль более ярким, добавляет фруктовость и смягчает характерные корнеплодные оттенки.\n\nИмбирь раскрывается сразу в двух компонентах — Campari и кордиале. Он добавляет пряное тепло, лёгкую остроту и помогает освежать восприятие после насыщенной и жирной пищи. Campari сохраняет классическую аперитивную горечь, а Martini Rosso добавляет винную округлость, сладость и пряность.\n\nГлавная идея коктейля — стать полноценным гастрономическим партнёром для мяса. Землистая сладость свёклы поддерживает жареные и копчёные оттенки, горечь Campari балансирует насыщенность блюда, а имбирь создаёт контраст и подготавливает рецепторы к следующему кусочку.\n\nАпельсиновая лодочка добавляет свежий цитрусовый аромат, а свекольная пудра визуально и вкусово возвращает гостя к основному ингредиенту.',
