      story:
        'Крымское Черноречье в авторской истории напитка становится местом, где природа и древность существуют рядом.\n\nМежду тёмными скалами, изъеденными временем, царит особая тишина. Её нарушают только ветер в ущельях и течение Чёрной реки. Каменистые тропы, предгорья и следы давно ушедших культур создают ощущение, будто прошлое всё ещё присутствует в долине.\n\nЭта атмосфера легла в основу Black River Negroni.\n\nКлассическая равнодольная структура коктейля дополняется крымским черносливом. Он придаёт напитку мягкую сладость, тёмный фруктовый профиль и бархатистое восприятие. Дым сливовой щепы добавляет тонкий копчёный шлейф, напоминающий о кострах в предгорьях и утреннем тумане над рекой.\n\nСначала раскрываются горечь Campari и винная пряность Martini Rosso. Затем появляется насыщенный вкус чернослива. В финале остаются древесные, смолистые и слегка дымные оттенки.\n\nBlack River Negroni — это классический коктейль, рассказанный через локальный крымский продукт и образ Чернореченской долины: строгий, терпкий и немного мистический.',
