      intro:
        'Red Rowan Negroni — ягодная интерпретация классического Negroni с русским сезонным акцентом. Джин на красной рябине соединяется с красным вермутом, Campari, Aperol и земляничным ликёром, создавая пряный сладко-горький профиль с оттенками осенних ягод, цитрусов и летней земляники.',
      story:
        'Red Rowan Negroni, или «Рябиновый Негрони», соединяет классическую структуру итальянского коктейля с образом русской осени.\n\nОсновой напитка становится London Dry Gin, настоянный на красной рябине. Ягода привносит характерную терпкость, лёгкую горечь и ощущение перехода от тёплого лета к прохладным осенним дням.\n\nMartini Rubino добавляет винную глубину, пряность и мягкую сладость. Campari сохраняет узнаваемый горький каркас Negroni, а Aperol делает цитрусовую часть легче и ярче.\n\nЗемляничный ликёр становится воспоминанием о лете. Его ягодная сладость смягчает рябиновую терпкость и связывает осенний характер коктейля с ароматом спелых лесных ягод.\n\nНебольшое количество сахарного сиропа округляет композицию, не меняя её основного направления. В результате вкус развивается от рябины и пряного вермута к земляничной сладости, цитрусовой горечи и продолжительному ягодно-травяному послевкусию.\n\nRed Rowan Negroni передаёт сезон через контраст: в нём одновременно остаются тепло летнего солнца, аромат ягод и свежесть осенних дождей.',
      image: '/images/recipes/Red Rowan Negroni.png',
      cardImage: '/images/cards/Red Rowan Negroni.png',
      method: 'Stir / стир',
      glass: 'Rocks / рокс',
