      intro:
        '«Кащей Бессмертный» — фруктово-ореховая интерпретация Negroni, вдохновлённая одним из самых загадочных персонажей русских сказок. Выдержанный дистиллят из хурмы соединяется с красным вермутом, Campari и вишнёво-миндальным кордиалом. Подача в окуренном дубовой щепой сундуке добавляет древесный аромат и усиливает мистический характер напитка.',
      story:
        '«Кащей Бессмертный» рассказывает историю одного из самых неоднозначных персонажей русских сказок.\n\nВ авторской интерпретации Кащей предстаёт не только злодеем, но и стражем — хранителем границы между мирами. Его сила скрыта, характер многослоен, а внешняя суровость сочетается с внутренней сложностью.\n\nЭту двойственность команда «Посольства» переносит во вкус коктейля.\n\nВместо классического для Negroni джина используется выдержанный в бочке дистиллят из хурмы. Хурму часто называют «оранжевым золотом»: она придаёт напитку плотный фруктовый профиль, мягкие ореховые оттенки и лёгкую танинность. Бочковая выдержка добавляет древесную глубину и делает основу более зрелой.\n\nКрасный сладкий вермут сохраняет винную пряность и связь с классической формулой. Campari отвечает за узнаваемую аперитивную горечь, а вишнёво-миндальный кордиал добавляет ягодную кислотность, косточковую сладость и тостовые ореховые ноты.\n\nКордиал слегка смягчает горечь, но не лишает коктейль характера. Вишня и миндаль поддерживают тёмную сказочную атмосферу, а хурма добавляет необычный фруктовый объём.\n\nФинальной частью истории становится подача. Бокал помещают в сундук, предварительно окуренный дубовой щепой. Когда сундук открывается, гостя встречает древесный дым — словно дверь между привычным миром и сказочной реальностью.',
