        'В итальянском проекте Enzo команда решила посмотреть на классический Negroni с гастрономической стороны.\n\nОтправной точкой стал лавровый лист — привычный для кухни ингредиент, способный добавить напитку сухую пряность, терпкость и узнаваемый тёплый аромат. В коктейле он уплотняет вкусовой профиль и делает классическую горько-сладкую структуру более выразительной.\n\nКомпозицию продолжают хересные и артишоковые оттенки. Херес добавляет винную глубину, сухость и лёгкие окислительные ноты, а артишоковый компонент формирует землисто-травяную горечь.\n\nСолевой акцент завершает баланс. В небольшой дозировке соль делает ароматические оттенки ярче, подчёркивает сладость и помогает связать горькие, винные и пряные компоненты.\n\nНегрони Enzo сохраняет связь с итальянской аперитивной классикой, но раскрывает её как гастрономический напиток — плотный, травянистый и рассчитанный на сочетание с едой.',
